        String emissionDiagnostic(SpawnerBlockEntity be){var bounds=EntityTypes.SPLASH_POTION.getSpawnAABB(impact.x,impact.y,impact.z);boolean resident=true;for(int x=net.minecraft.util.Mth.floor(bounds.minX)>>4;x<=net.minecraft.util.Mth.floor(bounds.maxX)>>4;x++)for(int z=net.minecraft.util.Mth.floor(bounds.minZ)>>4;z<=net.minecraft.util.Mth.floor(bounds.maxZ)>>4;z++)resident&=level.getChunkSource().getChunkNow(x,z)!=null;double nearest=Double.POSITIVE_INFINITY;var players=new ArrayList<String>();for(var player:level.players()){double distance=player.position().distanceTo(Vec3.atCenterOf(be.getBlockPos()));if(player.isAlive() && !player.isSpectator())nearest=Math.min(nearest,distance);players.add(player.getScoreboardName()+"@"+player.position()+" mode="+player.gameMode.getGameModeForPlayer()+" alive="+player.isAlive());}return "canTick="+game.items().potionSpawnerDrops().canTick(be)+" stopped="+game.items().timeStop().stopped(level)+" spawnersEnabled="+level.isSpawnerBlockEnabled()+" nearestEligibleDistance="+nearest+" requiredRange="+saved(be).getIntOr("RequiredPlayerRange",-1)+" noCollision="+level.noCollision(bounds)+" candidateResident="+resident+" residentBE="+(level.getBlockEntity(be.getBlockPos())==be)+" nearbyPotions="+count()+" players="+players;}
